const q = $json.query || {};
const mode = q['hub.mode'];
const token = q['hub.verify_token'];
const challenge = q['hub.challenge'];
const expected = $env.META_VERIFY_TOKEN || '0931234d935978f4527ec724e1a9c60e';

if (mode === 'subscribe' && token === expected) {
  return [{ json: { ok: true, challenge } }];
}

return [{ json: { ok: false, error: 'Verification token mismatch' } }];

const body = $json.body || {};
const value = body?.entry?.[0]?.changes?.[0]?.value || {};
const msg = value.messages?.[0] || null;
const statuses = value.statuses || [];
const store = $getWorkflowStaticData('global');
store.sequentialMessageQueues = store.sequentialMessageQueues || {};
store.sequentialMessageIndex = store.sequentialMessageIndex || {};

function queueSendOutput(queue, index) {
  const message = queue.messages[index];
  if (!message?.body) return null;
  queue.current_index = index;
  queue.updated_at = new Date().toISOString();
  queue.messages[index] = {
    ...message,
    status: 'ready_to_send',
    ready_at: new Date().toISOString(),
  };
  return {
    route: 'sequential_queue_send',
    queue_id: queue.queue_id,
    queue_index: index,
    queue_message_kind: message.kind || message.body?.type || 'message',
    graph_phone_number_id: queue.graph_phone_number_id,
    meta_access_token: queue.meta_access_token,
    meta_target_url: `https://graph.facebook.com/v23.0/${queue.graph_phone_number_id}/messages`,
    meta_request_body: message.body,
    raw: body,
  };
}

if (String(body.gentle_internal_event || '') === 'register_sequential_message_queue') {
  const rawMessages = Array.isArray(body.messages) ? body.messages : [];
  const messages = rawMessages
    .map((item, index) => ({
      index,
      kind: String(item?.kind || item?.body?.type || 'message'),
      body: item?.body && typeof item.body === 'object' ? item.body : null,
      status: 'pending',
      wamid: '',
    }))
    .filter((item) => item.body);
  const queueId = String(body.queue_id || `${body.conversation_id || 'conversation'}-${Date.now()}`).trim();
  const graphPhoneNumberId = String(body.graph_phone_number_id || '').trim();
  const metaAccessToken = String(body.meta_access_token || '').trim();

  if (!queueId || !messages.length || !graphPhoneNumberId || !metaAccessToken) {
    return [{ json: { route: 'queue_register_error', ok: false, error: 'missing_sequential_queue_fields' } }];
  }

  const queue = {
    queue_id: queueId,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    conversation_id: String(body.conversation_id || ''),
    recipient_id: String(body.recipient_id || ''),
    model_name: String(body.model_name || ''),
    graph_phone_number_id: graphPhoneNumberId,
    meta_access_token: metaAccessToken,
    current_index: -1,
    completed: false,
    messages,
  };
  store.sequentialMessageQueues[queueId] = queue;
  const first = queueSendOutput(queue, 0);
  return [{ json: first || { route: 'queue_register_error', ok: false, error: 'empty_queue' } }];
}

if (!msg) {
  const terminalStatuses = new Set(['sent']);
  const queueUpdates = [];
  let nextToSend = null;

  for (const statusEvent of statuses) {
    const messageId = String(statusEvent.id || '').trim();
    const queueId = store.sequentialMessageIndex[messageId];
    const queue = queueId ? store.sequentialMessageQueues[queueId] : null;
    if (!queue || queue.completed) continue;

    const messageIndex = queue.messages.findIndex((item) => item.wamid === messageId);
    if (messageIndex < 0) continue;

    const statusValue = String(statusEvent.status || '').trim().toLowerCase();
    const existingMessage = queue.messages[messageIndex] || {};
    queue.messages[messageIndex] = {
      ...existingMessage,
      status: statusValue,
      status_at: new Date().toISOString(),
      status_timestamp: statusEvent.timestamp || '',
    };
    queue.updated_at = new Date().toISOString();
    queueUpdates.push({ queue_id: queueId, message_id: messageId, index: messageIndex, status: statusValue });

    if (!terminalStatuses.has(statusValue) || messageIndex !== queue.current_index || nextToSend) continue;
    if (existingMessage.advanced_at) continue;

    queue.messages[messageIndex] = {
      ...queue.messages[messageIndex],
      advanced_at: new Date().toISOString(),
      advanced_by_status: statusValue,
    };
    delete store.sequentialMessageIndex[messageId];
    const nextIndex = messageIndex + 1;
    if (nextIndex >= queue.messages.length) {
      queue.completed = true;
      queue.completed_at = new Date().toISOString();
      continue;
    }

    if (queue.messages[nextIndex]?.status === 'pending') {
      nextToSend = queueSendOutput(queue, nextIndex);
    }
  }

  if (nextToSend) {
    nextToSend.sequential_queue_updates = queueUpdates;
    return [{ json: nextToSend }];
  }

  return [{ json: {
    route: statuses.length ? 'status' : 'ignore',
    raw: body,
    value,
    statuses,
    sequential_queue_updates: queueUpdates,
  }}];
}

const isFlowReply = msg.type === 'interactive' && msg.interactive?.type === 'nfm_reply';
const isButtonReply =
  (msg.type === 'button' && !!msg.button?.payload) ||
  (msg.type === 'interactive' && msg.interactive?.type === 'button_reply' && !!msg.interactive?.button_reply?.id) ||
  (msg.type === 'interactive' && msg.interactive?.type === 'list_reply' && !!msg.interactive?.list_reply?.id);

const phoneNumberId = value.metadata?.phone_number_id || '';
const waId = value.contacts?.[0]?.wa_id || msg.from || '';
const profileName = value.contacts?.[0]?.profile?.name || '';
const buttonPayload = msg.button?.payload || msg.interactive?.button_reply?.id || msg.interactive?.list_reply?.id || '';
const buttonText = msg.button?.text || msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';

let route = 'normal';
if (isFlowReply) route = 'flow';
else if (isButtonReply) route = 'button_reply';

$execution.customData.set('tipo', route);

return [{ json: {
  route,
  phone_number_id: phoneNumberId,
  wa_id: waId,
  profile_name: profileName,
  message_id: msg.id || '',
  timestamp: msg.timestamp || '',
  flow_token: msg.interactive?.nfm_reply?.flow_token || '',
  flow_name: msg.interactive?.nfm_reply?.name || '',
  response_json: msg.interactive?.nfm_reply?.response_json || {},
  button_payload: buttonPayload,
  button_text: buttonText,
  msg,
  raw: body,
}}];

const item = JSON.parse(JSON.stringify($json));

function parseResponseJson(value) {
  if (!value) return {};
  if (typeof value === 'object') return value;
  try {
    return JSON.parse(value);
  } catch (e) {
    return { raw_response_json: String(value) };
  }
}

function formatValue(value) {
  if (Array.isArray(value)) {
    return value.join(', ');
  }
  if (value && typeof value === 'object') {
    return JSON.stringify(value);
  }
  if (value === null || value === undefined || value === '') {
    return '-';
  }
  return String(value);
}

const data = parseResponseJson(item.response_json);

const lines = [];
for (const [key, value] of Object.entries(data)) {
  lines.push(`${key}: ${formatValue(value)}`);
}

const textBody = lines.join('\n');

const msg = item.raw?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];

if (!msg) {
  throw new Error('No se encontró raw.entry[0].changes[0].value.messages[0]');
}

// mantener todo igual y cambiar SOLO messages[0]
msg.type = 'text';
msg.text = {
  body: textBody
};

// quitar la parte interactiva
// delete msg.interactive;
// opcional: quitar context para que se parezca más al mensaje normal
// delete msg.context;

return [
  {
    json: item
  }
];

const item = JSON.parse(JSON.stringify($json));

const msg = item.raw?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
if (!msg) {
  throw new Error('No se encontró raw.entry[0].changes[0].value.messages[0]');
}

const payload = String(item.button_payload || msg.button?.payload || msg.interactive?.button_reply?.id || msg.interactive?.list_reply?.id || '').trim();
const buttonText = String(item.button_text || msg.button?.text || msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '').trim();
const listDescription = String(msg.interactive?.list_reply?.description || '').trim();
const isListReply = msg.type === 'interactive' && msg.interactive?.type === 'list_reply';

let model = '';
let action = '';

if (payload.includes('__')) {
  const parts = payload.split('__');
  model = String(parts[0] || '').trim();
  action = String(parts.slice(1).join('__') || '').trim();
}

const textLines = isListReply
  ? [
      'list_reply_id: ' + (payload || '-'),
      'list_reply_title: ' + (buttonText || '-'),
      'list_reply_description: ' + (listDescription || '-'),
      'selected_establishment_name: ' + (buttonText || '-'),
      'selected_establishment_id: ' + (payload.startsWith('est__') ? payload.slice(5) : '-'),
      'button_payload: ' + (payload || '-'),
    ]
  : [
      'button_action: ' + (action || '-'),
      'model: ' + (model || '-'),
      'button_text: ' + (buttonText || '-'),
      'button_payload: ' + (payload || '-'),
    ];

const textBody = textLines.join('\n');

msg.type = 'text';
msg.text = { body: textBody };
delete msg.button;
if (msg.interactive) delete msg.interactive;

return [{ json: item }];

//const exactYes = 'SI tengo visa americana';
//const exactNo = 'NO tengo visa americana';
const exactYes = 'Si, tengo Visa Americana';
const exactNo = 'No tengo Visa Americana';

const rawMessage = $json.raw?.entry?.[0]?.changes?.[0]?.value?.messages?.[0] || {};
const buttonText = String($json.button_text || '').trim();
const plainText = String(rawMessage?.text?.body || '').trim();
const responseText = buttonText || plainText;

if (![exactYes, exactNo].includes(responseText)) {
  return [];
}

const unixTimestamp = Number($json.timestamp || rawMessage?.timestamp || 0);
const timestampUtc = unixTimestamp
  ? new Date(unixTimestamp * 1000).toISOString()
  : new Date().toISOString();

return [{
  json: {
    TIMESTAMP_UTC: timestampUtc,
    PHONE_NUMBER: String($json.wa_id || rawMessage?.from || '').trim(),
    PROFILE_NAME: String($json.profile_name || '').trim(),
    RESPONSE_TEXT: responseText,
    RESPONSE_SHORT: responseText === exactYes ? 'SI' : 'NO',
    MESSAGE_ID: String($json.message_id || rawMessage?.id || '').trim(),
    TEMPLATE_NAME: 'hyundai_fifa_visa_check_ec',
    COUNT_VALUE: '1',
  },
}];

const store = $getWorkflowStaticData('global');
store.sequentialMessageQueues = store.sequentialMessageQueues || {};
store.sequentialMessageIndex = store.sequentialMessageIndex || {};

const sent = $json;
const source = $('If Sequential Queue Send').item.json;
const queueId = String(source.queue_id || '').trim();
const index = Number(source.queue_index);
const wamid = String(sent.messages?.[0]?.id || '').trim();
const queue = store.sequentialMessageQueues[queueId];

if (queue && Number.isInteger(index) && queue.messages?.[index]) {
  queue.messages[index] = {
    ...queue.messages[index],
    status: 'sent',
    wamid,
    sent_at: new Date().toISOString(),
  };
  queue.current_index = index;
  queue.updated_at = new Date().toISOString();
  if (wamid) store.sequentialMessageIndex[wamid] = queueId;
}

return [{ json: { ...source, send_response: sent, recorded_wamid: wamid, route: 'sequential_queue_sent' } }];
